contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 prevBalance, uint128 sentAmount, address randomUser) public {
        // sentAmount can be 0..max128 (plus prevBalance keeps sum in uint256 safe range without overflow)
        // restrict randomUser to something that won't cause issues (no preconditions, just ensure it's not contract on setup)
        vm.assume(randomUser != address(0) && randomUser != address(c));
        // Give the user some previous balance: call addToBalance with prevBalance, then reset to 0 and re-add
