pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDeposit, uint256 attackAmount) public {
        // Keep amounts in a reasonable range to avoid overflow (though SafeMath is used, keep it wide)
        initialDeposit = bound(initialDeposit, 1 ether, 100 ether);
        attackAmount = bound(attackAmount, 1 wei, initialDeposit); // attacker can only withdraw what they have

        // Deploy a reentrant attacker helper that will call addToBalance during withdrawBalance
        Attacker attacker = new Attacker(c);

        // Fund attacker
        vm.deal(address(attacker), initialDeposit);
        vm.prank(address(attacker));
        c.addToBalance{value: initialDeposit}();

        // Record attacker's balance in C before attack
        uint256 balanceBefore = c.getBalance(address(attacker));

        // Attacker triggers withdraw, which will re-enter addToBalance during the external call
        vm.prank(address(attacker));
        attacker.attack{value: attackAmount}();

        // After all calls complete, the invariant is:
        // sum of all user balances == address(c).balance
        // In the reference contract, reentrancy is prevented, so only the initial deposit is counted.
        // In the buggy contract, the reentrant addToBalance increases userBalance[attacker] without corresponding Ether.
        // We check that the attacker's balance matches the actual Ether they can withdraw (the contract's balance)
        // General rule: For the attacker, its recorded balance plus any Ether it sent should equal the contract's balance.
        // But simpler: The contract's balance should equal the attacker's recorded balance (since only attacker interacts).
        assertTrue(c.getBalance(address(attacker)) == address(c).balance);
    }
}

contract Attacker {
    C target;
    uint256 attackValue;
    bool attacked;

    constructor(C _target) {
        target = _target;
    }

    function attack() external payable {
        require(!attacked, "already attacked");
        attacked = true;
        attackValue = msg.value;
        target.withdrawBalance();
    }

    receive() external payable {
        // Re-enter addToBalance with the same Ether we just received?
        // No, we want to call addToBalance with the attackValue to increase our balance artificially.
        // But we need Ether for that. We'll use the Ether we just received from withdraw.
        // The withdraw sends userBalance[attacker] Ether. We'll forward that same Ether to addToBalance.
        // This will increase userBalance again in the buggy version.
        if (address(target).balance >= attackValue) {
            target.addToBalance{value: attackValue}();
        }
    }
}

