pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address attacker;
    ReentrancyExploit exploit;

    function setUp() public {
        c = new C();
        attacker = makeAddr("attacker");
        exploit = new ReentrancyExploit(c);
    }

    function testFuzz_property(uint256 amount) public {
        // Admissible domain: any non-zero amount up to a large bound to keep gas reasonable
        amount = bound(amount, 1, 100 ether);

        // Give the exploit contract Ether and let it addToBalance normally
        vm.deal(address(exploit), amount);

        // Record balance before the operation
        uint256 balanceBefore = c.getBalance(address(exploit));

        // The exploit contract calls addToBalance; it may try to re-enter
        exploit.initiateAddToBalance{value: amount}();

        // After the call completes, the userBalance of the exploit contract must equal its initial balance + amount
        uint256 balanceAfter = c.getBalance(address(exploit));
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}

contract ReentrancyExploit {
    C public target;
    bool public reentered;

    constructor(C _target) {
        target = _target;
    }

    function initiateAddToBalance() external payable {
        reentered = false;
        target.addToBalance{value: msg.value}();
    }

    receive() external payable {
        // Re-entrant call: if we haven't re-entered yet, trigger withdrawBalance to get another addToBalance
        if (!reentered && address(target).balance >= msg.value) {
            reentered = true;
            // withdrawBalance will send back our balance, triggering receive again
            target.withdrawBalance();
        }
    }
}

