pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 reentrantAmount) public {
        // Keep amounts in admissible range and non-zero to make state changes meaningful
        amount = bound(amount, 1, 100 ether);
        reentrantAmount = bound(reentrantAmount, 1, 50 ether);
        // Adversarial counterparty that attempts a re-entrant deposit during withdrawal
        ReentrantCaller attacker = new ReentrantCaller();
        uint256 attackerDeposit = amount;
        // Fund and deposit legitimate Ether from attacker
        vm.deal(address(attacker), attackerDeposit);
        vm.prank(address(attacker));
        c.addToBalance{value: attackerDeposit}();
        // Now attacker has a positive userBalance; re-entrant withdrawal is attempted
        // Fund the reentrant deposit amount (the attacker's contract itself has no extra ETH)
        vm.deal(address(attacker), reentrantAmount);
        attacker.setAttackParams(address(c), reentrantAmount);
        // The attacker's receive function calls back into c.addToBalance when receiving ETH
        vm.prank(address(attacker));
        try c.withdrawBalance() { } catch { }

        // Assertion: the attacker's userBalance must not exceed the total Ether the attacker actually sent
        uint256 totalSentByAttacker = attackerDeposit + reentrantAmount;
        assertTrue(c.getBalance(address(attacker)) <= totalSentByAttacker);
    }
}

contract ReentrantCaller {
    C target;
    uint256 reenterValue;
    bool inAttack;

    function setAttackParams(address _target, uint256 _reenterValue) external {
        target = C(_target);
        reenterValue = _reenterValue;
        inAttack = true;
    }

    receive() external payable {
        if (inAttack) {
            inAttack = false;
            target.addToBalance{value: reenterValue}();
        }
    }
}

