import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;
    function setUp() public {
        c = new C();
        attacker = new ReentrantAttacker(address(c));
    }
    function testFuzz_property(uint256 val) public {
        // val must be in admissible domain: non-zero, no overflow when doubled, and >0 to trigger reentrancy
        vm.assume(val > 0 && val < type(uint256).max / 2);
        vm.deal(address(attacker), val);
        attacker.trigger(val);
        // After the attack, the attacker's balance in C must equal exactly val (the single msg.value)
        // The correct contract locks out the reentrant call, so only msg.value is added.
