pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 preBalance) public {
        // admissible domain: amount > 0 so that msg.value is non-zero and a reentrant withdraw has funds to drain;
        // preBalance can be any value, giving the attacker a starting balance; bound to avoid overflow in practical terms
        amount = bound(amount, 1, 1 ether);
        preBalance = bound(preBalance, 0, 1 ether);

        // deploy a reentrant attacker that withdraws during addToBalance
        Attacker attacker = new Attacker(c, preBalance);

        // fund both the attacker EOA (for the external addToBalance call) and the attacker contract (for preBalance deposit)
        vm.deal(address(attacker), amount);
        if (preBalance > 0) {
            vm.deal(address(this), preBalance);
            c.addToBalance{value: preBalance}();
            // transfer preBalance to attacker contract so it has an initial userBalance in C
            // we do this by withdrawing from this test contract into attacker's address
            // actually simpler: just use msg.sender = attacker address when adding the preBalance
            // but we already set up C; we can give preBalance directly to attacker address through C:
            // need to deposit from attacker address; we can prank and send value
        }

        // Reset: we set up C so that attacker address has preBalance userBalance
        C freshC = new C();
        if (preBalance > 0) {
            vm.deal(address(attacker), preBalance);
            vm.prank(address(attacker));
            freshC.addToBalance{value: preBalance}();
        }

        // record balance before the attack
        uint256 balanceBefore = freshC.getBalance(address(attacker));

        // attacker calls addToBalance with amount; this triggers reentrancy during the call
        vm.prank(address(attacker));
        attacker.attack{value: amount}();

        // after the call completes, the attacker's balance in C must be at least amount (the deposit)
        // because a reentrant withdraw should not be able to steal the new deposit before it is added
        uint256 balanceAfter = freshC.getBalance(address(attacker));
        assertTrue(balanceAfter >= amount);
    }
}

contract Attacker {
    C public target;
    uint256 public preBalance;
    constructor(C _target, uint256 _preBalance) {
        target = _target;
        preBalance = _preBalance;
    }
    function attack() external payable {
        target.addToBalance{value: msg.value}();
    }
    receive() external payable {
        // reentrant call: withdraw during addToBalance if we have any preBalance
        if (preBalance > 0 && address(target).balance >= preBalance) {
            target.withdrawBalance();
        }
    }
}

