pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 withdrawAmt, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmt > 0);
        vm.assume(withdrawAmt > 0);
        vm.assume(withdrawAmt <= depositAmt);

        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.addToBalance{value: depositAmt}();

        uint256 balanceBefore = c.getBalance(actor);

        // attacker that re-enters when receiving ether
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(actor, withdrawAmt);
        vm.prank(actor);
        (bool s1,) = address(attacker).call{value: withdrawAmt}("");
        require(s1);
        attacker.initiate();

        uint256 balanceAfter = c.getBalance(actor);

        // The invariant: after any call that results in the balance being zero, it must remain zero.
        // The bug causes the balance to be zero after the first withdraw but the second withdraw fails to reset it properly.
        assertTrue(balanceAfter == 0);
    }
}

contract ReentrantAttacker {
    C target;
    bool reentered;
    constructor(C _target) { target = _target; reentered = false; }
    function initiate() external {
        target.withdrawBalance();
    }
    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.withdrawBalance();
        }
    }
}

