pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address user1, address user2, address recipient) public {
        // Bound amounts to avoid overflow in addToBalance
        amount1 = bound(amount1, 1, type(uint120).max);
        amount2 = bound(amount2, 1, type(uint120).max);
        // Ensure users are distinct, not the zero address, and not the contract itself
        vm.assume(user1 != address(0) && user2 != address(0));
        vm.assume(user1 != address(c) && user2 != address(c));
        vm.assume(user1 != user2);

        // Fund user1 and make a deposit
        vm.deal(user1, amount1);
        vm.prank(user1);
        c.addToBalance{value: amount1}();
        assertEq(c.getBalance(user1), amount1);

        // First withdrawBalance by user1 should succeed
        bool firstOk;
        vm.prank(user1);
        try c.withdrawBalance() { firstOk = true; } catch { firstOk = false; }
        assertTrue(firstOk);
        assertEq(c.getBalance(user1), 0);

        // Now user1 deposits again (same or different amount) and attempts a second withdrawal.
        // The re-entrancy guard prevents a second call from succeeding.
        vm.deal(user1, amount2);
        vm.prank(user1);
        c.addToBalance{value: amount2}();
        assertEq(c.getBalance(user1), amount2);

        bool secondOk;
        vm.prank(user1);
        // The rule: a second call to withdrawBalance MUST revert (locked_ is still true in the buggy version)
        // In the reference, locked_ is false after the first withdraw so this second call succeeds.
        try c.withdrawBalance() { secondOk = true; } catch { secondOk = false; }
        // The invariant: second withdrawal MUST always fail because the guard should be stuck locked.
        // In the reference (correct) version locked_ is false, so the call succeeds and this assertion fails,
        // but the correct rule is that it must fail (revert).
        // Actually the requirement is: "test that PASSES on reference and FAILS on buggy".
        // To align with that, we assert that after a successful first withdrawal and a re-deposit,
        // the second withdrawal succeeds for the reference but fails for the buggy version.
        // So we assert *the opposite* of the above comment: we assert that the second call succeeds.
        // Let's invert: reference succeeds → secondOk should be true. Buggy fails → secondOk is false.
        assertTrue(secondOk);
    }
}

